/*	Builds the response page. Somebody can be asked two ways: as a candidate invited
	through Email to Contacts, who is not on the event, or as somebody a coordinator
	staffed first and then invited through Email to Staff. Both must be able to answer.
	Only reached with a valid personal token. Every form carries the token, so the
	response handler can check it again before recording anything.
	Role names and the verb both come from config, never hardcoded, so the page reads in
	your own vocabulary	*/

const cfg = $('Config').first().json;
const link = $('Extract link').first().json;
const api = $input.first().json;

const event = (api.data || {}).event || null;
const responder = (api.data || {}).responder || null;

const coordRole = String(cfg.COORDINATOR_ROLE_NAME).trim();
const fallbackRole = String(cfg.FALLBACK_ROLE_NAME || 'Instructor').trim();

/*	The verb for what an instructor does with an event. Two forms are needed because the
	sentences below use both: deliver this event, and delivering this event. The literals here
	are a last resort if config is ever blank, not the setting - change VERB_BASE and
	VERB_GERUND in Config	*/
const verb = String(cfg.VERB_BASE || 'deliver').trim();
const verbing = String(cfg.VERB_GERUND || 'delivering').trim();

/*	Every invitation row for this event. The responder's own row may not exist yet -
	absent is the normal first click	*/
const rows = $('Read Prior Response').all().map(i => i.json).filter(r => r && r.event_id);
const prior = rows.find(r => String(r.contact_id) === String(link.contactId)) || null;

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const prettyDate = (iso) => {
	if (!iso) { return ''; }
	const d = new Date(String(iso).replace(' ', 'T'));
	if (isNaN(d.getTime())) { return String(iso); }
	const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
	return months[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
};

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

/*	Two kinds of page that are not the form, and they are not the same thing.
	refuse is for something genuinely wrong, so it ends by pointing at a human.
	closeOff is for when everything is in order and there is simply nothing to do	*/
const refuse = (heading, message) => [{ json: { valid: false, html: page(heading, '<h1>' + esc(heading) + '</h1><div class="notice error"><p>' + esc(message) + '</p></div><p>Please reply to the invitation email and someone will help.</p>') } }];

const closeOff = (heading, message) => [{ json: { valid: false, html: page(heading, '<h1>' + esc(heading) + '</h1><div class="notice"><p>' + esc(message) + '</p></div><p>You can close this page.</p>') } }];

const blockedHeading = 'Answer cannot be recorded yet';

if (!event) { return refuse('This invitation is no longer active', 'The link may be incomplete, or the event may no longer exist.'); }

const staff = ((event.staff || {}).edges || []).map(e => e.node);

/*	Whether anybody holds the coordinator role on this event. This is a separate problem
	from the one below: it does not stop an answer, it stops anybody being told about it	*/
const hasCoordinator = staff.some(s => String((s.staffRole || {}).name || '').trim() === coordRole);

/*	The coordinator is staff on the event, so they are recognised from staffing	*/
const me = staff.find(s => s.contact && s.contact.id === link.contactId) || null;
const isCoordinator = me !== null && String((me.staffRole || {}).name || '').trim() === coordRole;

/*	The responder's own staff record, read from the staff list rather than from required
	personnel so it still resolves when required personnel is unset. The coordinator role
	is skipped because a coordinator is not one of the people ' + verbing + ' the event	*/
const myStaff = staff.find(s => s.contact
	&& s.contact.id === link.contactId
	&& String((s.staffRole || {}).name || '').trim() !== coordRole) || null;

const alreadyOn = myStaff !== null;

const header = '<h1>Are you available to ' + esc(verb) + ' ' + esc(event.title) + '?</h1>'
	+ '<p class="meta"><span>' + esc(prettyDate(event.classroomStart)) + '</span>'
	+ (event.location ? ' &middot; <span>' + esc(event.location.name) + '</span>' : '') + '</p>';

/*	Which roles this event still needs. Roles are custom defined per tenant and an event
	can require more than one, so this is read from the event rather than assumed	*/
let requiredRoleCount = 0;
const requiredOpen = [];

for (const req of (event.requiredStaff || [])) {
	const roleName = String((req.staffRole || {}).name || '').trim();
	const roleId = String((req.staffRole || {}).id || '');
	const qty = Number(req.quantity || 0);
	if (roleName === coordRole || qty === 0) { continue; }
	requiredRoleCount = requiredRoleCount + 1;
	const holders = staff.filter(s => String((s.staffRole || {}).name || '').trim() === roleName);
	if (holders.length < qty) { requiredOpen.push({ id: roleId, name: roleName }); }
}

const slotsFilled = requiredRoleCount > 0 && requiredOpen.length === 0;
const neededRole = requiredOpen.length > 0 ? requiredOpen[0].name : fallbackRole;

/*	Coordinator view: record a response that arrived some other way.
	The picker comes from the invitations table, since candidates are not on the event	*/
if (isCoordinator) {
	const answered = ['accepted', 'declined'];
	const open = rows.filter(r => answered.indexOf(String(r.status || '').toLowerCase()) === -1 && String(r.status || '') !== 'coordinator');

	if (open.length === 0) {
		return closeOff('Nothing outstanding to record', 'Everybody we know about on this event has already given a firm answer. Somebody appears here once they have asked for their personal link or answered.');
	}

	const options = open.map(r => '<option value="' + esc(r.contact_id) + '">' + esc(r.contact_name || r.contact_email || r.contact_id) + '</option>').join('');

	const body = '<h1>Record a response for ' + esc(event.title) + '</h1>'
		+ '<p class="meta"><span>' + esc(prettyDate(event.classroomStart)) + '</span>'
		+ (event.location ? ' &middot; <span>' + esc(event.location.name) + '</span>' : '') + '</p>'
		+ '<div class="notice"><p>You are the ' + esc(coordRole) + ' for this event. Use this page to record a response that arrived another way, such as a direct email reply.</p></div>'
		+ '<form method="post" action="' + esc(cfg.SUBMIT_URL) + '">'
		+ '<input type="hidden" name="e" value="' + esc(link.eventId) + '">'
		+ '<input type="hidden" name="c" value="' + esc(link.contactId) + '">'
		+ '<input type="hidden" name="t" value="' + esc(link.linkToken) + '">'
		+ '<p><label class="block" for="behalf">Recording a response for</label><select id="behalf" name="behalf_contact_id" required><option value="">Choose a person</option>' + options + '</select></p>'
		+ '<fieldset><legend>Their answer</legend>'
		+ '<div class="choice"><input type="radio" id="a-yes" name="answer" value="yes" required><label for="a-yes">Yes<span class="hint">They will be assigned to ' + esc(verb) + ' this event.</span></label></div>'
		+ '<div class="choice"><input type="radio" id="a-no" name="answer" value="no"><label for="a-no">No<span class="hint">If they are already on the event, they will be taken off it.</span></label></div>'
		+ '<div class="choice"><input type="radio" id="a-maybe" name="answer" value="maybe"><label for="a-maybe">Maybe<span class="hint">Their link stays open, so they can still give a firm answer.</span></label></div>'
		+ '</fieldset>'
		+ '<p><label class="block" for="comments">Comments</label><textarea id="comments" name="comments" aria-describedby="comments-help"></textarea>'
		+ '<span class="help" id="comments-help">Record what they actually said. It is stored exactly as written.</span></p>'
		+ '<p><button type="submit">Record this response</button></p></form>';

	return [{ json: { valid: true, html: page('Record a response', body) } }];
}

/*	Candidate view	*/
if (!responder) { return refuse('This invitation is no longer active', 'The link may be incomplete.'); }

/*	The next three are all in order rather than wrong, so none of them sends the reader
	off to find help. Each already says what to do if the reader disagrees	*/
if (prior && String(prior.status || '') === 'declined') {
	return closeOff('You have already declined', 'We recorded that you are not available for this event. If that has changed, reply to the invitation email and we will pick it up.');
}

/*	Being on the event is not the same as having answered. Somebody the coordinator
	staffed first is on it and has still not been asked, so only a recorded acceptance
	closes the page	*/
if (alreadyOn && prior && String(prior.status || '') === 'accepted') {
	return closeOff('You are already confirmed', 'You have accepted this event and are assigned to ' + verb + ' it. Nothing further is needed.');
}

/*	A full event does not shut out one of the people who is themselves filling it	*/
if (slotsFilled && !alreadyOn) {
	return closeOff('This event is now fully staffed', 'Somebody else accepted before we heard from you, so no response is needed. Thank you for considering it.');
}

/*	Two distinct reasons an answer cannot be honoured, and they are told apart because
	the remedy differs. Either the contact record is missing the role this event needs,
	which is what addStaff enforces, or the record is not marked as able to do this at
	all. Whether a coordinator exists is a third, separate matter, handled below	*/
const myRoleIds = (responder.staffRoles || []).map(r => String(r.id));
const holdableOpen = requiredOpen.filter(r => myRoleIds.indexOf(r.id) !== -1);
const canHoldRole = requiredRoleCount === 0
	? myRoleIds.indexOf(String(cfg.FALLBACK_ROLE_ID)) !== -1
	: holdableOpen.length > 0;

const isEligible = responder.isInstructor === true || responder.isQualified === true;

if (!alreadyOn && (!canHoldRole || !isEligible)) {
	if (prior && String(prior.status || '') === 'assign_failed') {
		return closeOff('We have already passed this on', 'The ' + coordRole + ' knows your record needs updating for this event, and will be in touch.');
	}

	const blockedReason = !canHoldRole
		? 'This event needs a ' + neededRole + ', and your contact record does not have that role yet. Until it is added, an answer cannot be saved against the event.'
		: 'Your contact record is not marked as able to ' + verb + ' events yet. Until that is set, an answer cannot be saved against the event.';

	/*	No coordinator on the event is a second and separate problem. It does not cause
		the blockage, it removes the person who would normally fix it	*/
	if (!hasCoordinator) {
		return [{ json: { valid: false, html: page(blockedHeading,
			'<h1>' + esc(blockedHeading) + '</h1>'
			+ '<div class="notice error"><p>' + esc(blockedReason) + '</p></div>'
			+ '<p>This event has no ' + esc(coordRole) + ' for us to pass it to, so please reply to the invitation email and somebody will sort both out.</p>') } }];
	}

	return [{ json: { valid: false, html: page(blockedHeading,
		'<h1>' + esc(blockedHeading) + '</h1>'
		+ '<div class="notice error"><p>' + esc(blockedReason) + '</p></div>'
		+ '<p>Tell the ' + esc(coordRole) + ' and they will get it added.</p>'
		+ '<form method="post" action="' + esc(cfg.SUBMIT_URL) + '">'
		+ '<input type="hidden" name="e" value="' + esc(link.eventId) + '">'
		+ '<input type="hidden" name="c" value="' + esc(link.contactId) + '">'
		+ '<input type="hidden" name="t" value="' + esc(link.linkToken) + '">'
		+ '<input type="hidden" name="answer" value="unable">'
		+ '<p><label class="block" for="comments">Anything you want to add</label><textarea id="comments" name="comments" aria-describedby="comments-help"></textarea>'
		+ '<span class="help" id="comments-help">Optional. For example, whether you would still like to ' + esc(verb) + ' this event.</span></p>'
		+ '<p><button type="submit">Tell the ' + esc(coordRole) + '</button></p></form>') } }];
}

const assignedNotice = alreadyOn
	? '<div class="notice"><p>You have been put down to ' + esc(verb) + ' this event. Please confirm whether you are available.</p></div>'
	: '';

/*	Each hint says what happens if you pick it, and nothing else. Restating the choice
	before explaining it just repeats the label, and it was the reason the three did not
	read as a set: two restated, one went straight to instruction	*/
const yesHint = alreadyOn
	? 'Your place on this event stands.'
	: 'You will be assigned to ' + verb + ' this event.';

const noHint = alreadyOn
	? 'You will be taken off this event and we will ask somebody else.'
	: 'We will ask somebody else.';

const maybeHint = 'Your link stays open, and the ' + coordRole + ' will get back to you. Use the comments to say what you need to know.';

const body = header.replace('</p>', ' &middot; <span>' + esc(responder.firstName + ' ' + responder.lastName) + '</span></p>')
	+ assignedNotice
	+ (prior && String(prior.status || '') === 'maybe' ? '<div class="notice"><p>You told us maybe last time. You can give a firm answer now.</p></div>' : '')
	+ '<form method="post" action="' + esc(cfg.SUBMIT_URL) + '">'
	+ '<input type="hidden" name="e" value="' + esc(link.eventId) + '">'
	+ '<input type="hidden" name="c" value="' + esc(link.contactId) + '">'
	+ '<input type="hidden" name="t" value="' + esc(link.linkToken) + '">'
	+ '<fieldset><legend>Your answer</legend>'
	+ '<div class="choice"><input type="radio" id="a-yes" name="answer" value="yes" required><label for="a-yes">Yes<span class="hint">' + esc(yesHint) + '</span></label></div>'
	+ '<div class="choice"><input type="radio" id="a-no" name="answer" value="no"><label for="a-no">No<span class="hint">' + esc(noHint) + '</span></label></div>'
	+ '<div class="choice"><input type="radio" id="a-maybe" name="answer" value="maybe"><label for="a-maybe">Maybe<span class="hint">' + esc(maybeHint) + '</span></label></div>'
	+ '</fieldset>'
	+ '<p><label class="block" for="comments">Comments</label><textarea id="comments" name="comments" aria-describedby="comments-help"></textarea>'
	+ '<span class="help" id="comments-help">Optional. Anything you write is recorded exactly as written and read by a person.</span></p>'
	+ '<p><button type="submit">Send my response</button></p></form>';

return [{ json: { valid: true, html: page('Invitation to ' + verb + ' an event', body) } }];

/*	Every link that can lead to a recorded answer carries a random token that is stored on
	the invitation row. Without a matching token this page shows nothing about the event.
	It offers to email the person their own personal link instead, as a button rather than
	automatically, because mail scanners open links but do not press buttons.
	Nothing is written here	*/

const cfg = $('Config').first().json;
const link = $('Extract link').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.event_id);
const row = rows.find((r) => String(r.contact_id) === String(link.contactId)) || null;

/*	Compares in constant time, so response timing does not leak how much of a guess
	was right. An empty token never matches	*/
const sameToken = (expected, given) => {
	const a = String(expected || '');
	const b = String(given || '');
	if (a === '' || b === '' || a.length !== b.length) { return false; }
	let diff = 0;
	for (let i = 0; i < a.length; i++) { diff = diff | (a.charCodeAt(i) ^ b.charCodeAt(i)); }
	return diff === 0;
};

const hasIds = String(link.eventId || '') !== '' && String(link.contactId || '') !== '';

if (hasIds && row !== null && sameToken(row.token, link.linkToken)) {
	return [{ json: { valid: true } }];
}

const esc = (v) => String(v === null || v === undefined ? '' : v)
	.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');

const page = (title, body) => '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title><style>' + cfg.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc(cfg.BRAND_NAME) + '</p></header><main>' + body + '</main></body></html>';

const hasToken = String(link.linkToken || '') !== '';

const heading = hasToken ? 'This link is invalid or has expired' : 'Get your personal response link';
const message = hasToken
	? 'This link is not valid any more, so nothing can be recorded from it. A newer link may have replaced it.'
	: 'For your security, answers are only accepted through a personal link that we email to you.';

const action = hasIds
	? '<form method="post" action="' + esc(cfg.SUBMIT_URL) + '">'
		+ '<input type="hidden" name="e" value="' + esc(link.eventId) + '">'
		+ '<input type="hidden" name="c" value="' + esc(link.contactId) + '">'
		+ '<input type="hidden" name="action" value="request_link">'
		+ '<p>We can email a personal link to the address we hold for you.</p>'
		+ '<p><button type="submit">Email me my link</button></p></form>'
	: '<p>The link is incomplete. Please reply to the invitation email and someone will help.</p>';

return [{ json: {
	valid: false,
	html: page(heading, '<h1>' + esc(heading) + '</h1><div class="notice' + (hasToken ? ' error' : '') + '"><p>' + esc(message) + '</p></div>' + action)
} }];
